def transform(grid):
    g = np.array(grid)
    rows = [y for y, c in dividers(g)["rows"]]
    bounds = []
    start = 0
    for r in rows + [g.shape[0]]:
        if r > start:
            bounds.append((start, r - 1))
        start = r + 1
    P = [g[a:b + 1].copy() for a, b in bounds]
    H, W = P[0].shape

    def changed(a, b):
        return set(int(x) for x in np.where((a != b).any(axis=0))[0])

    C = [changed(P[i], P[i + 1]) for i in range(len(P) - 1)]
    # find constant column offset d
    d = 0
    for cand in range(-W + 1, W):
        if all(set(x + cand for x in C[i]) == C[i + 1] for i in range(len(C) - 1)):
            d = cand
            break

    def left(p, y, x):
        xx = x - d
        return int(p[y][xx]) if 0 <= xx < W else -1

    table = {}
    for i in range(len(P) - 1):
        for x in C[i]:
            for y in range(H):
                table[(int(P[i][y][x]), left(P[i], y, x))] = int(P[i + 1][y][x])

    last = P[-1]
    out = last.copy()
    emit(out, "Start from the last panel of the sequence.")
    newC = [x + d for x in C[-1] if 0 <= x + d < W]
    for x in newC:
        for y in range(H):
            key = (int(last[y][x]), left(last, y, x))
            if key in table:
                out[y][x] = table[key]
    emit(out, f"Advance one step: rewrite columns {sorted(newC)} (previous changed columns shifted by {d}) using the learned cell transitions.")
    return out
